// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 val, address caller) public {
        vm.assume(caller != address(0));

        vm.prank(caller);
        bool ok;
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.MinSum() == val);
        } else {
            assertTrue(c.MinSum() == c.MinSum());
        }
    }
}
